  "quiz": [
    {
      "id": "q1",
      "q": "二十年前，青石河的「河神」每年中秋向村里索要什么？",
      "options": [
        {
          "key": "A",
          "text": "一船新稻"
        },
        {
          "key": "B",
          "text": "一对童男童女"
        },
        {
          "key": "C",
          "text": "三牲与香火"
        },
        {
          "key": "D",
          "text": "一口铜钟"
        }
      ],
      "answer": "B",
      "clue": "fr_he_3",
      "explain": "何晓得客房里的旧土地簿记着：青石河神，赤鳞，每岁中秋索童男童女一对。"
    },
    {
      "id": "q2",
      "q": "当年被抬上花轿的青石村小姑娘刘小莲，和千灯洞里的哪个人是一家？",
      "options": [
        {
          "key": "A",
          "text": "刘大勺"
        },
        {
          "key": "B",
          "text": "何晓得"
        },
        {
          "key": "C",
          "text": "吴七丝"
        },
        {
          "key": "D",
          "text": "戚玉蝎"
        }
      ],
      "answer": "A",
      "clue": "fr_liu_4",
      "explain": "灶房砖缝里压着青石河神庙的中秋供单和一截红头绳；土地簿记着童女刘小莲的哥哥拦轿被打折左腿，刘大勺姓刘，左腿是瘸的。"
    },
    {
      "id": "q3",
      "q": "戚玉蝎嫁给甄长生之前，原本是谁的妻子？",
      "options": [
        {
          "key": "A",
          "text": "毒敌山蝎王"
        },
        {
          "key": "B",
          "text": "盘丝岭的洞主"
        },
        {
          "key": "C",
          "text": "青石河的河伯"
        },
        {
          "key": "D",
          "text": "白骨岭的山神"
        }
      ],
      "answer": "A",
      "clue": "fr_qi_4",
      "explain": "寝殿妆匣最底下压着一截断了的金色蝎尾钩，钩根铸着毒敌山三字。"
    },
    {
      "id": "q4",
      "q": "宝库里被记作「借出未还」的，是哪三件宝贝？",
      "options": [
        {
          "key": "A",
          "text": "传音螺、照妖灯、本命灯"
        },
        {
          "key": "B",
          "text": "避水镜、风火珠、金丝笼"
        },
        {
          "key": "C",
          "text": "骨匣、蛛丝绳、逆鳞膏"
        },
        {
          "key": "D",
          "text": "金击子、紫金铃、芭蕉扇"
        }
      ],
      "answer": "B",
      "clue": "fr_sa_2",
      "explain": "撒千谋案上的宝库副簿记着避水镜、风火珠、金丝笼三件借出未还，宝库角落的三只锦盒也是空的。"
    },
    {
      "id": "q5",
      "q": "大铁角的弟弟二犇，是怎么没的？",
      "options": [
        {
          "key": "A",
          "text": "被唐僧的徒弟打死"
        },
        {
          "key": "B",
          "text": "去年秋天奉命去山口拦天庭神将，没能回来"
        },
        {
          "key": "C",
          "text": "偷了宝库的夜明珠被剥了皮"
        },
        {
          "key": "D",
          "text": "失足掉进寒潭"
        }
      ],
      "answer": "B",
      "clue": "fr_da_3",
      "explain": "先锋营床头的小牛角系着白布，背面写着：去年秋，山口拦神将，未归。"
    },
    {
      "id": "q6",
      "q": "鬼白娘的本命骨，当初为什么会押在甄长生手里？",
      "options": [
        {
          "key": "A",
          "text": "她和甄长生打赌输了"
        },
        {
          "key": "B",
          "text": "甄长生护住了她的残魂，她以本命骨作押"
        },
        {
          "key": "C",
          "text": "她偷了千灯洞的宝贝被扣下"
        },
        {
          "key": "D",
          "text": "她把本命骨当作聘礼送给了他"
        }
      ],
      "answer": "B",
      "clue": "fr_gui_4",
      "explain": "小骨匣里的契纸写着：感甄长生护残魂之恩，本命骨一节押于其处，事成归还。"
    },
    {
      "id": "q7",
      "q": "吴七丝为什么答应来千灯洞？",
      "options": [
        {
          "key": "A",
          "text": "想来盗取传音螺"
        },
        {
          "key": "B",
          "text": "六个姐姐被甄长生的小妖困在盘丝洞"
        },
        {
          "key": "C",
          "text": "想做千灯洞的夫人"
        },
        {
          "key": "D",
          "text": "受天庭之托来降妖"
        }
      ],
      "answer": "B",
      "clue": "fr_wu_4",
      "explain": "吴七丝包袱里六姐的信写着盘丝洞口守着的小妖又多了一倍；枕下那张放人令也是为了让小妖撤走。"
    }
  ],
